"""Expand prefix string by adding a trailing period if needed.

    expandPrefix(p) should be used instead of p+'.' in most contexts.
    """
def expandPrefix(prefix: Any) -> object {
    if (prefix and not prefix.endswith('.')) {
        return (prefix + '.');
    }
    return prefix;
}

